--- Custom textures. The PNGs are generated by tools/build_assets.py into res/
--- and are not in git; without them the mod still runs, with vanilla looks.

local Assets = {}
SSB.Assets = Assets

local HERO_SHEET = "res/hero.png"

register_option_bool("keep_character", "Keep my selected character",
    "Play as the character picked on the character select screen (or any character pack"
    .. " installed for it) instead of this mod's own hero. Takes effect at the next level.",
    false)

--- True when the player asked to keep their own character.
local function keeping_character()
    return type(options) == "table" and options.keep_character == true
end

local hero_texture = nil
local replaced = {} -- vanilla texture id -> true, for undoing

--- The hero sheet has the layout of a vanilla character sheet (2048 x 2048, 128
--- pixel cells), so the definition is copied from one and only the file swapped.
local function define_hero()
    if hero_texture ~= nil then
        return hero_texture
    end
    if not PackFileExists(HERO_SHEET) then
        print("[SSB] " .. HERO_SHEET .. " is missing: run  python tools/build_assets.py"
            .. "  in the pack folder. Playing with the vanilla character for now.")
        return nil
    end
    local def = get_texture_definition(TEXTURE.DATA_TEXTURES_CHAR_YELLOW_0)
    def.texture_path = HERO_SHEET
    hero_texture = define_texture(def)
    return hero_texture
end

--- Swap one vanilla character sheet for the hero's. Replacing the sheet (rather
--- than only an entity's texture) also covers the whip and the rope, which are
--- drawn from the same sheet.
--- @return string? # what happened, or nil if nothing needed doing
local function replace_sheet(vanilla)
    local texture = define_hero()
    if texture == nil then
        return "hero texture: missing file"
    end
    if vanilla == nil or vanilla == texture or replaced[vanilla] then
        return nil
    end
    if replace_texture(vanilla, texture) then
        replaced[vanilla] = true
        return "hero texture: replaced vanilla texture " .. tostring(vanilla)
    end
    return "hero texture: replace_texture refused for " .. tostring(vanilla)
end

--- Before a level is generated: replace the sheet of the character player 1
--- picked. It has to happen before the player entity exists: an entity that is
--- already spawned keeps drawing the sheet it was created with (seen in game:
--- the first level showed the vanilla character, later levels the hero).
--- @return string
function Assets.dress_before_spawn()
    if keeping_character() then
        Assets.restore()
        return "hero texture: keeping the selected character (option)"
    end
    local ok, vanilla = pcall(function()
        return state.items.player_select[1].texture
    end)
    if not ok or vanilla == nil then
        return "hero texture: could not read player 1's character before spawn"
    end
    return replace_sheet(vanilla) or "hero texture: already applied"
end

--- At level start, for whatever dress_before_spawn could not cover: if the sheet
--- was only replaced now, the player entity is given the texture directly too.
--- @param p userdata
--- @return string # what happened, for the trace header
function Assets.dress_hero(p)
    if keeping_character() then
        return "hero texture: keeping the selected character (option)"
    end
    local result = replace_sheet(p:get_texture())
    if result == nil then
        return "hero texture: already applied"
    end
    if hero_texture ~= nil then
        p:set_texture(hero_texture)
        result = result .. ", and set on the player entity"
    end
    return result
end

--- True while the hero's own sheet is what the player is drawn from. Only that
--- sheet has the extra skid cell; a vanilla-layout sheet does not.
--- @return boolean
function Assets.hero_sheet_in_use()
    return next(replaced) ~= nil
end

--- Put every replaced vanilla texture back.
function Assets.restore()
    for vanilla, _ in pairs(replaced) do
        pcall(reset_texture, vanilla)
    end
    replaced = {}
end

return Assets
